import{_ as i,H as e,f as l,i as n}from"./chunks/framework.nyB-Xt5O.js";const h=JSON.parse('{"title":"KM 6. BI 工具与可视化（BI Tools & Visualization）","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge-map/km-6-bi-visualization/index.md","filePath":"knowledge-map/km-6-bi-visualization/index.md","lastUpdated":1779798726000}'),t={name:"knowledge-map/km-6-bi-visualization/index.md"};function o(s,a,r,d,u,m){return e(),l("div",null,[...a[0]||(a[0]=[n('<h1 id="km-6-bi-工具与可视化-bi-tools-visualization" tabindex="-1">KM 6. BI 工具与可视化（BI Tools &amp; Visualization） <a class="header-anchor" href="#km-6-bi-工具与可视化-bi-tools-visualization" aria-label="Permalink to &quot;KM 6. BI 工具与可视化（BI Tools &amp; Visualization）&quot;">​</a></h1><blockquote><p>数据可视化是将分析结果有效传达给决策者的最终环节。本节从<strong>视觉认知原理</strong>出发，深入图表选择、仪表板设计、数据叙事，并覆盖 Tableau、Power BI 和开源 BI 工具的实战技能。</p></blockquote><h2 id="章节" tabindex="-1">章节 <a class="header-anchor" href="#章节" aria-label="Permalink to &quot;章节&quot;">​</a></h2><ol><li><a href="/data-analysis-learning/knowledge-map/km-6-bi-visualization/01-principles">可视化原理</a> — 格式塔原则、预注意属性、图表选择决策树、色彩理论、标注基础、无障碍设计</li><li><a href="/data-analysis-learning/knowledge-map/km-6-bi-visualization/02-chart-types">图表类型详解</a> — 柱状图/折线图/散点图/直方图/箱线图/热力图/树图/瀑布图等使用场景与常见错误、图表选择黄金法则</li><li><a href="/data-analysis-learning/knowledge-map/km-6-bi-visualization/03-dashboard-design">Dashboard 设计</a> — 信息层级与 F 型/Z 型扫描模式、KPI 布局规则、执行型 vs 运营型 Dashboard 设计、交互设计（下钻/筛选/交叉筛选）</li><li><a href="/data-analysis-learning/knowledge-map/km-6-bi-visualization/04-storytelling">Data Storytelling</a> — Context → Conflict → Resolution → Action 叙事结构、Insight → Conclusion → Recommendation 框架、数据演示组织结构、渐进式揭示与强制对比技巧</li><li><a href="/data-analysis-learning/knowledge-map/km-6-bi-visualization/05-tableau">Tableau 实战</a> — 数据连接（Live/Extract）、计算字段、表计算（分区与寻址）、LOD 表达式（FIXED/INCLUDE/EXCLUDE）、参数、集与动作、Dashboard 交互性、性能优化</li><li><a href="/data-analysis-learning/knowledge-map/km-6-bi-visualization/06-powerbi">Power BI 实战</a> — DAX 核心函数（CALCULATE/FILTER/ALL/SUMX）、常用度量值模式、Power Query M 语言、行级安全性 RLS、模型视图设计原则、Gateway 部署</li><li><a href="/data-analysis-learning/knowledge-map/km-6-bi-visualization/07-open-source">开源方案</a> — Metabase（部署/SQL 变量/权限）、Apache Superset（部署/60+ 图表/SQL Lab）、Metabase vs Superset vs Tableau vs Power BI 全面对比与选型建议</li></ol><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li><a href="/data-analysis-learning/learning-paths/path-2-core/05-visualization">学习路径：数据可视化与报告</a> — 快速入门版本</li><li><a href="/data-analysis-learning/learning-paths/path-2-core/03-bi-tools">学习路径：BI 工具</a> — BI 工具选型指南</li></ul>',6)])])}const b=i(t,[["render",o]]);export{h as __pageData,b as default};
